/**
 * The in-app logo.
 *
 * Upstream this was Excalidraw's own mark — a hand holding a pencil, plus a
 * path-drawn "Excalidraw" wordmark — rendered as the centrepiece of the welcome
 * screen. Shipping it in a product called Firo would have been a brand
 * violation, so it is replaced.
 *
 * ## This is a placeholder
 *
 * Firo has no designed identity yet. The product name is a working name pending
 * a trademark check, and no palette has been chosen (see `docs/roadmap.md`).
 * Rather than invent a brand, this renders the same neutral mark as
 * `public/favicon.svg`, which is generated by
 * `scripts/brand/generate-icons.py`.
 *
 * Keeping the two in sync is deliberate: the app and its favicon should not
 * disagree. When a real mark is designed, change the generator and this file
 * together.
 *
 * The wordmark is gone rather than restyled. Drawing "Firo" as SVG paths is a
 * design task, and a wrong-looking wordmark is worse than none — the product
 * name is in the document title and the tab.
 *
 * The component is named `FiroLogo`, not `ExcalidrawLogo`, because the old name
 * reached the DOM as a CSS class. The broader `Excalidraw*` → `Firo*` rename of
 * internal symbols is deferred to Phase 3, but a class name that spells out
 * another product's trademark is not something to leave sitting in a stylesheet.
 */
import "./FiroLogo.scss";

const LogoIcon = () => (
  <svg
    viewBox="0 0 1000 1000"
    fill="none"
    xmlns="http://www.w3.org/2000/svg"
    className="FiroLogo-icon"
    role="img"
    aria-label="Firo"
  >
    {/* Geometry mirrors public/favicon.svg: a rounded ink tile with two chalk
        strokes and a connector, strokes centred on the tile. */}
    <rect
      x="85"
      y="85"
      width="830"
      height="830"
      rx="161.3"
      ry="161.3"
      fill="currentColor"
    />
    <g
      stroke="var(--color-surface, #fff)"
      strokeWidth="58"
      strokeLinecap="round"
      fill="none"
    >
      <line x1="355" y1="365" x2="535" y2="365" />
      <line x1="355" y1="635" x2="645" y2="635" />
      <line x1="355" y1="365" x2="355" y2="635" />
    </g>
  </svg>
);

type LogoSize = "xs" | "small" | "normal" | "large" | "custom" | "mobile";

interface LogoProps {
  size?: LogoSize;
  /**
   * Accepted and ignored. Upstream this toggled a path-drawn wordmark; Firo has
   * no wordmark (see the module comment). Kept so the call site does not need
   * changing when one is designed.
   */
  withText?: boolean;
  style?: React.CSSProperties;
}

export const FiroLogo = ({ style, size = "small" }: LogoProps) => {
  return (
    <div className={`FiroLogo is-${size}`} style={style}>
      <LogoIcon />
    </div>
  );
};
